  }
}];

const source = $json.body ?? $json;

const request = {
  requester_name: String(source.requester_name ?? "").trim(),
  requester_email: String(source.requester_email ?? "").trim(),
  department: String(source.department ?? "").trim(),
  item_name: String(source.item_name ?? "").trim(),
  description: String(source.description ?? "").trim(),
  quantity: Number(source.quantity ?? 0),
  estimated_amount: Number(source.estimated_amount ?? 0),
  currency: String(source.currency ?? "PKR").trim().toUpperCase(),
  urgency: String(source.urgency ?? "normal").trim().toLowerCase()
};

const missing_fields = [];

if (!request.requester_name) missing_fields.push("requester_name");
if (!request.requester_email) missing_fields.push("requester_email");
if (!request.department) missing_fields.push("department");
if (!request.item_name) missing_fields.push("item_name");
if (!Number.isFinite(request.quantity) || request.quantity <= 0) missing_fields.push("quantity");
if (!Number.isFinite(request.estimated_amount) || request.estimated_amount <= 0) missing_fields.push("estimated_amount");

return [{
  json: {
    request,
    is_complete: missing_fields.length === 0,
    missing_fields
  }
}];

const items = $input.all();
return [{
  json: {
    policies: items.map(item => item.json)
  }
}];

