const request = $('Normalize & Validate').first().json.request;
const policies = $('Collect Policies').first().json.policies;

const rawText = $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error("Gemini returned no structured text.");
}

let ai;
try {
  ai = JSON.parse(rawText);
} catch (error) {
  throw new Error(`Could not parse Gemini JSON: ${rawText}`);
}

const matchingRules = policies.filter(rule =>
  rule.is_active === true &&
  rule.rule_type === "approval_threshold" &&
  String(rule.currency || "PKR").toUpperCase() === request.currency
);

let approvalRequired = false;
const matchedRules = [];

for (const rule of matchingRules) {
  const threshold = Number(rule.threshold_amount);
  if (Number.isFinite(threshold) && request.estimated_amount > threshold) {
    approvalRequired = true;
    matchedRules.push({
      id: rule.id,
      rule_name: rule.rule_name,
      threshold_amount: threshold,
      currency: rule.currency,
      action_required: rule.action_required
    });
  }
}

const status = approvalRequired ? "needs_approval" : "sourcing";

return [{
  json: {
    request,
    ai_analysis: ai,
    requires_manager_approval: approvalRequired,
    matched_rules: matchedRules,
    status
  }
}];

const saved = $json;
const decision = $('Apply Procurement Policy').first().json;

return [{
  json: {
    purchase_request_id: saved.id,
    saved_request: saved,
    ...decision
  }
}];

